// Patches the v4 table with the K1 n-dial literals from t8v4. Does not overwrite v4.
// Do not edit this file after it has run.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const src = JSON.parse(readFileSync(resolve('work/out/accept-table-t8-v4.json'), 'utf8'));
const DIAL = 'f3e460f19a599a9059655304852b53b15fbbf81cefb3f90b6325e736712c23ca';
const STOCK = [14, 2, 2, 0, 27, 0, 39, 0, 0, 0];
src.table = 'accept-table-t8-v5';
src.presets.halfSingle = {
  k99a1: [3, 0, 2, 0, 2, 0, 5, 5],
  k9a41: [0, 1],
  k5962: [292, 526, 526, 526, 526, 526],
  k1dd1: [7, 9, 3, 3, 3, 3, 3, 3, 3, 3],
  k84d1: [6],
  k88b2: [292],
  k90d1: [3, 2, 2, 2, 2, 2, 5, 5],
  k5a11: [1, 1, 1, 0, 1, 0, 0, 0, 0, 1, 1],
  k1de1: [1, 1, 1, 1, 1, 1, 1, 1],
  k1df1: [1, 1, 1, 1, 0, 0, 0, 0, 1],
  k1db1: [1],
  k1dc1: [1],
};
for (const step of src.steps) {
  if (step.id === 'n-dial') step.expect.title = DIAL;
  if (!step.id.startsWith('edge-')) continue;
  const t = step.expect.target;
  if (Array.isArray(t)) step.expect.target = STOCK;
  else if (t && typeof t === 'object') {
    t.k1 = STOCK;
    t.k2 = STOCK;
  }
}
writeFileSync(resolve('work/out/accept-table-t8-v5.json'), JSON.stringify(src, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, dial: DIAL, stock: STOCK }) + '\n');
